INSERT INTO role_permissions (role_id, permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='manager' AND p.code IN ('departments.view','departments.create','departments.edit','job_titles.view','job_titles.create','job_titles.edit','users.create','users.edit') ON CONFLICT DO NOTHING;
